(()=>{const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const modal=document.getElementById('previewModal'),body=document.getElementById('previewBody'),title=document.getElementById('previewTitle');function value(root,selector,fallback=''){return root.querySelector(selector)?.value?.trim()||fallback;}function checked(root,selector){return root.querySelector(selector)?.checked!==false;}function selectedText(root,selector){return[...(root.querySelector(selector)?.selectedOptions||[])].map(o=>o.textContent.trim());}function build(exp){const accent=value(exp,'.brand-accent','#0c66e4'),brand=value(exp,'.brand-name',''),logo=value(exp,'.brand-logo',''),heading=value(exp,'.exp-heading','Service dashboard'),subtitle=value(exp,'.exp-subtitle',''),heroTitle=value(exp,'.brand-hero-title',''),heroText=value(exp,'.brand-hero-text',''),supportLabel=value(exp,'.brand-support-label','Support'),supportUrl=value(exp,'.brand-support-url',''),ann=[...exp.querySelectorAll('.announcement')].map(a=>({title:value(a,'.ann-title'),body:value(a,'.ann-body'),style:value(a,'.ann-style','info')})).filter(a=>a.title||a.body),cats=[...exp.querySelectorAll('.category')].map(c=>({name:value(c,'.cat-name','Service'),description:value(c,'.cat-desc'),requests:[...c.querySelectorAll('.rt:checked')].map(x=>x.closest('label')?.querySelector('strong')?.textContent||'Request')})).filter(c=>c.requests.length),links=[...exp.querySelectorAll('.useful-link')].map(l=>({label:value(l,'.link-label'),description:value(l,'.link-desc')})).filter(l=>l.label),mobileName=value(exp,'.mobile-name',brand||'Portal+');title.textContent=`Preview — ${value(exp,'.exp-name','Customer experience')}`;body.style.setProperty('--preview-accent',accent);body.innerHTML=`<div class="preview-device"><div class="preview-brand"><div class="preview-lockup">${logo?`<img src="${esc(logo)}" alt="">`:''}<div>${brand?`<span class="preview-brand-name">${esc(brand)}</span>`:''}<h2>${esc(heading)}</h2><p>${esc(subtitle)}</p></div></div>${supportUrl?`<button>${esc(supportLabel)}</button>`:''}</div>${heroTitle||heroText?`<div class="preview-hero">${heroTitle?`<strong>${esc(heroTitle)}</strong>`:''}${heroText?`<span>${esc(heroText)}</span>`:''}</div>`:''}${ann.length?`<div class="preview-announcements">${ann.map(a=>`<div class="preview-ann ${esc(a.style)}"><strong>${esc(a.title)}</strong><span>${esc(a.body)}</span></div>`).join('')}</div>`:''}<div class="preview-cards">${checked(exp,'.d-open')?'<div><small>Open requests</small><strong>7</strong></div>':''}${exp.querySelector('.d-customer')?.checked?'<div><small>Awaiting you</small><strong>2</strong></div>':''}${exp.querySelector('.d-support')?.checked?'<div><small>Awaiting support</small><strong>5</strong></div>':''}<div><small>Visible requests</small><strong>12</strong></div></div>${exp.querySelector('.d-action')?.checked?'<section><h3>Things needing your attention</h3><div class="preview-action">! <span><strong>Example request needing your response</strong><small>REQ-102 · Awaiting customer</small></span></div></section>':''}${cats.length?`<section><h3>Services & Quick Actions</h3><div class="preview-services">${cats.map(c=>`<article><strong>${esc(c.name)}</strong>${c.description?`<p>${esc(c.description)}</p>`:''}<div>${c.requests.slice(0,3).map(r=>`<span>${esc(r)} →</span>`).join('')}</div></article>`).join('')}</div></section>`:''}${links.length?`<section><h3>Useful resources</h3><div class="preview-links">${links.slice(0,3).map(l=>`<div><strong>${esc(l.label)}</strong><small>${esc(l.description)}</small></div>`).join('')}</div></section>`:''}<div class="preview-mobile-note"><strong>Mobile identity</strong><span>${esc(mobileName)}</span>${selectedText(exp,'.exp-audience').length?`<small>Audience: ${esc(selectedText(exp,'.exp-audience').join(', '))}</small>`:'<small>Fallback experience</small>'}</div></div>`;modal.hidden=false;document.body.classList.add('modal-open');}document.addEventListener('click',e=>{const preview=e.target.closest('.preview');if(preview){e.preventDefault();e.stopImmediatePropagation();build(preview.closest('.experience'));return;}if(e.target.closest('[data-close-preview]')||e.target===modal){modal.hidden=true;document.body.classList.remove('modal-open');}},true);document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!modal.hidden){modal.hidden=true;document.body.classList.remove('modal-open');}});})();